{
  "query": "mutation ($correo: String!, $clave: String!) {
  login(correo: $correo, clave: $clave) {
    token
    expiraEn
    nombre
    establecimientoId
    rol
  }
}",
  "variables": {
    "correo": "admin@demo.com",
    "clave": "demo1234"
  }
}

{
  "query": "query ($est: ID!) {\n  profesionales(establecimientoId: $est) { id nombre activo }\n  servicios(establecimientoId: $est) { id nombre duracionMinutos precio }\n}",
  "variables": {
    "est": "{{establecimientoId}}"
  }
}

{
  "query": "query ($prof: ID!, $desde: String!, $hasta: String!) {
  agenda(profesionalId: $prof, desde: $desde, hasta: $hasta) {
    id
    inicio
    estado
    servicio
    duracionMinutos
    valorCobrado
  }
}",
  "variables": {
    "prof": "{{profesionalId}}",
    "desde": "{{desde}}",
    "hasta": "{{hasta}}"
  }
}

{
  "query": "query ($prof: ID!, $desde: String!, $hasta: String!) {
  agenda(profesionalId: $prof, desde: $desde, hasta: $hasta) {
    id
    inicio
    estado
    servicio
    confirmadaEn
  }
}",
  "variables": {
    "prof": "{{profesionalId}}",
    "desde": "{{desde}}",
    "hasta": "{{hasta}}"
  }
}

{
  "query": "query ($prof: ID!, $serv: ID!, $fecha: String!) {\n  disponibilidad(profesionalId: $prof, servicioId: $serv, fecha: $fecha) {\n    inicio\n    fin\n  }\n}",
  "variables": {
    "prof": "{{profesionalId}}",
    "serv": "{{servicioId}}",
    "fecha": "{{fecha}}"
  }
}

{
  "query": "query ($est: ID!, $desde: String!, $hasta: String!) {
  inventario(establecimientoId: $est) {
    nombre
    existencia
    umbralMinimo
    enUmbral
  }
  resumenIngresos(establecimientoId: $est, desde: $desde, hasta: $hasta) {
    serviciosPrestados
    totalIngresos
  }
}",
  "variables": {
    "est": "{{establecimientoId}}",
    "desde": "{{desde}}",
    "hasta": "{{hasta}}"
  }
}

{
  "query": "query ($est: ID!) {
  notificaciones(establecimientoId: $est) {
    tipo
    asunto
    cuerpo
    creadaEn
  }
}",
  "variables": {
    "est": "{{establecimientoId}}"
  }
}

{
  "query": "query ($est: ID!) {
  clientesInactivos(establecimientoId: $est) {
    clienteId
    ultimaVisita
    proximoContacto
    totalVisitas
  }
}",
  "variables": {
    "est": "{{establecimientoId}}"
  }
}

{
  "query": "mutation ($est: ID!, $prof: ID!, $serv: ID!, $cli: ID!,\n          $inicio: String!, $fin: String!) {\n  reservarCita(establecimientoId: $est, profesionalId: $prof,\n               servicioId: $serv, clienteId: $cli,\n               inicio: $inicio, fin: $fin) {\n    id\n    inicio\n    estado\n  }\n}",
  "variables": {
    "est": "{{establecimientoId}}",
    "prof": "{{profesionalId}}",
    "serv": "{{servicioId}}",
    "cli": "{{clienteId}}",
    "inicio": "{{inicioGql}}",
    "fin": "{{finGql}}"
  }
}

{
  "query": "mutation ($id: ID!, $valor: Float!) {\n  cerrarCita(citaId: $id, valorCobrado: $valor) {\n    id\n    estado\n    valorCobrado\n  }\n}",
  "variables": {
    "id": "{{citaGqlId}}",
    "valor": 45000
  }
}

{
  "query": "mutation ($id: ID!, $por: String!, $motivo: String) {\n  cancelarCita(citaId: $id, canceladaPor: $por, motivo: $motivo) {\n    id\n    estado\n  }\n}",
  "variables": {
    "id": "{{citaGqlId}}",
    "por": "cliente",
    "motivo": "Cambio de planes"
  }
}
